// Exact exported generic Atlas only. Loopback; no Website auth, private studies or PACS.
import fs from 'node:fs';import path from 'node:path';import http from 'node:http';import assert from 'node:assert/strict';
import {hash,json} from './seal-simple-website-successor.mjs';
const stage='F:/VisibleMedicine/staging/20261024-orbital-desktop-audit',receipt='F:/VisibleMedicine/staging/20261024-orbital-ct-website/SOURCE_BOUND.json';
assert.equal(hash(receipt),'bdbb6eada06ea817ec27ef1da386563be94c5a417a140b03e37c54bf17e0a758');const source=json(receipt),root=source.website+'/public/atlas-runtime/head-neck',manifest=json(root+'/manifest.json');
assert(!fs.existsSync(stage));assert.equal(manifest.sourceCommit,source.atlasHead);assert.equal(manifest.patientDataIncluded,false);assert.equal(manifest.clinicalApproved,false);
const pointer=json('CURRENT_CHECKPOINT.json');assert.equal(pointer.activeWork.current.ownerPreviewPolicy.restartPermitted,false);assert.equal(pointer.activeWork.current.activeExecutionSessions.length,0);
const files=new Map();for(const r of manifest.files){assert.equal(hash(root+'/'+r.path),r.sha256,r.path);files.set('/atlas-runtime/head-neck/'+r.path,root+'/'+r.path);}
fs.mkdirSync(stage);fs.mkdirSync(stage+'/browser');const requests=[];
const write=(p,v)=>fs.writeFileSync(stage+'/'+p,JSON.stringify(v,null,2)+'\n',{flag:'wx'});
const server=http.createServer((req,res)=>{const url=new URL(req.url,'http://qa.invalid'),file=files.get(url.pathname);requests.push({at:new Date().toISOString(),path:url.pathname,method:req.method,registered:!!file});res.setHeader('Cache-Control','no-store');if(req.method!=='GET'||!file){res.writeHead(404);res.end('Not registered');return;}res.setHeader('Content-Type',({'.html':'text/html;charset=utf-8','.js':'text/javascript;charset=utf-8','.css':'text/css;charset=utf-8','.json':'application/json','.glb':'model/gltf-binary','.txt':'text/plain'})[path.extname(file)]??'application/octet-stream');res.end(fs.readFileSync(file));});
function state(active){const p=json('CURRENT_CHECKPOINT.json');p.activeWork.current.activeExecutionSessions=p.activeWork.current.activeExecutionSessions.filter(r=>r.role!=='orbital-desktop-audit');if(active)p.activeWork.current.activeExecutionSessions.push({role:'orbital-desktop-audit',pid:process.pid,evidence:stage,previewChanged:false});const text=JSON.stringify(p,null,2)+'\n';assert(Buffer.byteLength(text)<65536);fs.writeFileSync('CURRENT_CHECKPOINT.json',text);}
let closing=false;function close(reason){if(closing)return;closing=true;server.close(()=>{write('REQUESTS.json',requests);write('TERMINAL.json',{at:new Date().toISOString(),pid:process.pid,code:0,reason,graceful:true,previewChanged:false});state(false);process.exit(0);});}
server.listen(0,'127.0.0.1',()=>{const base='http://127.0.0.1:'+server.address().port;write('STARTED.json',{at:new Date().toISOString(),base,pid:process.pid,sourceReceipt:receipt,sourceReceiptSha256:hash(receipt),sourceCommit:source.atlasHead,manifestSha256:hash(root+'/manifest.json'),registeredAssetsOnly:true,applicationBytesUnmodified:true,privateDataOrStudiesServed:false,authOrPermissionChanges:false,previewChanged:false});state(true);console.log(JSON.stringify({base,url:base+'/atlas-runtime/head-neck/index.html?region=whole-body',pid:process.pid,quit:'q'}));});
process.stdin.setEncoding('utf8');process.stdin.on('data',s=>{if(s.trim()==='q')close('q');});process.stdin.on('end',()=>close('stdin-ended'));process.on('SIGINT',()=>close('SIGINT'));process.on('SIGTERM',()=>close('SIGTERM'));
